-- Plano de contas do VIOS (export "Vios Jurídico - Plano de Contas.xlsx").
-- O item do VIOS só traz o grupo (nível 2) e o plano (nível 3); o nível 1
-- (ex.: 8 = DESPESAS COM PESSOAS) vem daqui. Usado no OPEX para agrupar os
-- grupos de conta pelo nível superior.

CREATE TABLE IF NOT EXISTS public.financeiro_plano_contas (
  codigo       text PRIMARY KEY,
  n1           integer NOT NULL,
  n2           integer NOT NULL,
  n3           integer NOT NULL,
  n4           integer NOT NULL,
  nivel        smallint NOT NULL CHECK (nivel BETWEEN 1 AND 4),
  nome         text NOT NULL,
  caminho      text NOT NULL,
  natureza     text,
  descricao    text,
  mostrar_dre  boolean NOT NULL DEFAULT true,
  updated_at   timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.financeiro_plano_contas IS
  'Plano de contas do VIOS. codigo no mesmo formato de financeiro_parcelas_itens.conta_numero (8.1.01.000). nivel 1 = grupo raiz (DESPESAS COM PESSOAS), 2 = grupo da conta (REMUNERAÇÃO FIXA), 3 = plano (HONORÁRIOS ASSOCIADOS).';
COMMENT ON COLUMN public.financeiro_plano_contas.nome IS 'Nome só do próprio nível (sem o caminho dos pais).';
COMMENT ON COLUMN public.financeiro_plano_contas.caminho IS 'Nome completo como o VIOS exporta ("DESPESAS COM PESSOAS - REMUNERAÇÃO FIXA").';

CREATE INDEX IF NOT EXISTS financeiro_plano_contas_nivel_idx
  ON public.financeiro_plano_contas (nivel, n1, n2);

ALTER TABLE public.financeiro_plano_contas ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS financeiro_plano_contas_select ON public.financeiro_plano_contas;
CREATE POLICY financeiro_plano_contas_select ON public.financeiro_plano_contas
  FOR SELECT TO authenticated, anon USING (true);

GRANT SELECT ON public.financeiro_plano_contas TO anon, authenticated;

ON CONFLICT (codigo) DO UPDATE SET
  n1 = EXCLUDED.n1,
  n2 = EXCLUDED.n2,
  n3 = EXCLUDED.n3,
  n4 = EXCLUDED.n4,
  nivel = EXCLUDED.nivel,
  nome = EXCLUDED.nome,
  caminho = EXCLUDED.caminho,
  natureza = EXCLUDED.natureza,
  descricao = EXCLUDED.descricao,
  mostrar_dre = EXCLUDED.mostrar_dre,
  updated_at = now();
